import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,)):
    """Call fn(); on failure sleep base * 2**n (capped, full jitter) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** n)))


if __name__ == "__main__":
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise ConnectionError
        return "ok"

    assert retry(flaky, base=0.01) == "ok" and len(calls) == 3
```

Usage: `retry(lambda: requests.get(url, timeout=5), exceptions=(requests.RequestException,))`.

Narrow `exceptions`: default `Exception` also retries bugs (`TypeError`, `KeyError`). Only retry idempotent calls. Full jitter → concurrent clients don't retry in sync.

